class InProcessProvider:
    """进程内子 Agent Provider。

    共享父 Agent 的 LLM 客户端和工具注册表，
    在独立的消息上下文中执行任务。
    """

    def __init__(self, llm_client, tools, config=None):
        self._llm = llm_client
        self._tools = tools
        self._config = config or {}

    @property
    def name(self) -> str:
        return 'in-process'

    @property
    def description(self) -> str:
        return '进程内子 Agent（共享 LLM/工具）'

    async def execute(self, request: SubagentRequest) -> SubagentResult:
        start = asyncio.get_event_loop().time()

        try:
            # 构造子 Agent 的系统提示
            system_prompt = self._config.get('subagent_system_prompt', '')
            if not system_prompt:
                system_prompt = (
                    '你是一个子 Agent，负责完成特定任务。'
                    '请简洁、准确地完成任务并返回结果。'
                )

            # 构造消息
            messages = [
                {'role': 'system', 'content': system_prompt},
                {'role': 'user', 'content': request.task},
            ]

            # 添加上下文
            if request.context:
                ctx_str = '\n'.join(
                    f'- {k}: {v}' for k, v in request.context.items()
                )
                messages.insert(1, {
                    'role': 'system',
                    'content': f'[上下文信息]\n{ctx_str}',
                })

            # 调用 LLM（带超时）
            timeout_s = request.timeout_ms / 1000
            response = await asyncio.wait_for(
                self._llm.chat(messages),
                timeout=timeout_s,
            )

            duration = (asyncio.get_event_loop().time() - start) * 1000

            return SubagentResult(
                success=True,
                output=response.get('content', '') if isinstance(response, dict) else str(response),
                provider=self.name,
                duration_ms=duration,
            )

        except asyncio.TimeoutError:
            return SubagentResult(
                success=False,
                error=f'子 Agent 执行超时 ({request.timeout_ms}ms)',
                provider=self.name,
                duration_ms=request.timeout_ms,
            )
        except Exception as e:
            logger.debug('InProcess 子 Agent 执行失败', exc_info=True)
            return SubagentResult(
                success=False,
                error=str(e),
                provider=self.name,
            )

    def health_check(self) -> dict:
        return {'provider': self.name, 'status': 'ok'}


