# A2A Provider (远程调用适配)
# ─────────────────────────────────────────

class A2ASubagentProvider:
    """A2A 远程子 Agent Provider。

    包装已有的 A2A Caller，适配 SubagentProviderProtocol。
    """

    def __init__(self, caller, agent_card=None):
        self._caller = caller
        self._agent_card = agent_card

    @property
    def name(self) -> str:
        return 'a2a'

    @property
    def description(self) -> str:
        card = self._agent_card
        if card:
            return f'A2A 远程 Agent: {card.get("name", "unknown")}'
        return 'A2A 远程子 Agent'

    async def execute(self, request: SubagentRequest) -> SubagentResult:
        start = asyncio.get_event_loop().time()

        try:
            result = await self._caller.invoke(
                task=request.task,
                context=request.context,
            )

            duration = (asyncio.get_event_loop().time() - start) * 1000

            if isinstance(result, dict) and result.get('success'):
                return SubagentResult(
                    success=True,
                    output=result.get('result', ''),
                    provider=self.name,
                    duration_ms=duration,
                    metadata=result,
                )
            else:
                error = result.get('error', '未知错误') if isinstance(result, dict) else str(result)
                return SubagentResult(
                    success=False,
                    error=error,
                    provider=self.name,
                    duration_ms=duration,
                )

        except Exception as e:
            logger.debug('A2A 子 Agent 调用失败', exc_info=True)
            return SubagentResult(
                success=False,
                error=str(e),
                provider=self.name,
            )

    def health_check(self) -> dict:
        return {'provider': self.name, 'status': 'ok'}


