class ForkProvider:
    """Fork 子 Agent Provider。

    从当前会话分叉出独立的子 Agent，
    拥有自己的消息上下文但共享 LLM/工具。
    """

    def __init__(self, llm_client, tools, session_log=None):
        self._llm = llm_client
        self._tools = tools
        self._session_log = session_log

    @property
    def name(self) -> str:
        return 'fork'

    @property
    def description(self) -> str:
        return '会话分叉子 Agent（独立上下文）'

    async def execute(self, request: SubagentRequest) -> SubagentResult:
        start = asyncio.get_event_loop().time()

        try:
            # 构造独立的消息上下文
            messages = [
                {'role': 'system', 'content': '你是从主会话分叉出的子 Agent，专注于完成分配的任务。'},
            ]

            # 注入父会话的上下文摘要
            if request.context.get('parent_summary'):
                messages.append({
                    'role': 'system',
                    'content': f'[父会话摘要] {request.context["parent_summary"]}',
                })

            messages.append({'role': 'user', 'content': request.task})

            timeout_s = request.timeout_ms / 1000
            response = await asyncio.wait_for(
                self._llm.chat(messages),
                timeout=timeout_s,
            )

            duration = (asyncio.get_event_loop().time() - start) * 1000

            return SubagentResult(
                success=True,
                output=response.get('content', '') if isinstance(response, dict) else str(response),
                provider=self.name,
                duration_ms=duration,
                metadata={'fork_id': str(uuid.uuid4())[:8]},
            )

        except asyncio.TimeoutError:
            return SubagentResult(
                success=False,
                error=f'Fork 子 Agent 超时 ({request.timeout_ms}ms)',
                provider=self.name,
            )
        except Exception as e:
            logger.debug('Fork 子 Agent 执行失败', exc_info=True)
            return SubagentResult(
                success=False,
                error=str(e),
                provider=self.name,
            )

    def health_check(self) -> dict:
        return {'provider': self.name, 'status': 'ok'}


# ─────────────────────────────────────────
# Codex CLI Provider（参考 deepseek-harness subagent-codex）
# ─────────────────────────────────────────

class CodexSubagentProvider:
    """Codex CLI 子 Agent Provider。

    参考 deepseek-harness 的 subagent-codex 模式：
    - 通过 `codex exec` CLI 子进程调用 Codex 模型
    - 支持 JSON 输出模式解析结构化结果
    - 自动审批（--dangerously-bypass-approvals-and-sandbox）
    - 工作目录继承父 Agent

    底层调用：
        codex exec [--model MODEL] [--json] "任务描述"

    配置项（config.json 或 DEFAULTS）：
        codex_command: codex 可执行文件路径（默认 "codex"）
        codex_model: 使用的模型（默认 "gpt-5.4"）
        codex_timeout: 超时毫秒数（默认 120000）
        codex_bypass_sandbox: 是否绕过沙箱（默认 True）
    """

    def __init__(self, config=None):
        self._config = config or {}
        self._codex_bin = self._config.get('codex_command', 'codex')
        self._model = self._config.get('codex_model', 'gpt-5.4')
        self._timeout_ms = int(self._config.get('codex_timeout', 120_000))
        self._bypass = self._config.get('codex_bypass_sandbox', True)
        self._available = None  # 懒检测

    @property
    def name(self) -> str:
        return 'codex'

    @property
    def description(self) -> str:
        return f'Codex CLI 子 Agent（模型: {self._model}）'

    def _check_available(self) -> bool:
        """检测 codex CLI 是否可用（结果缓存）。"""
        if self._available is not None:
            return self._available
        import shutil
        self._available = shutil.which(self._codex_bin) is not None
        if self._available:
            logger.info('Codex CLI 已检测: %s', self._codex_bin)
        else:
            logger.debug('Codex CLI 未找到: %s', self._codex_bin)
        return self._available

    async def execute(self, request: SubagentRequest) -> SubagentResult:
        from .tool_probe import find_binary_simple
        start = asyncio.get_event_loop().time()

        binary, status = find_binary_simple(self._codex_bin)
        if not binary:
            return SubagentResult(
                success=False,
                error=(
                    f'Codex CLI 未安装。请运行: npm install -g @openai/codex'
                ),
                provider=self.name,
            )

        try:
            # 构建 codex exec 命令（使用完整路径）
            cmd = [binary, 'exec']

            # 模型选择
            if self._model:
                cmd.extend(['--model', self._model])

            # JSON 输出模式（便于解析）
            cmd.append('--json')

            # 跳过审批和沙箱（全自动执行）
            if self._bypass:
                cmd.append('--dangerously-bypass-approvals-and-sandbox')

            # 工作目录
            cwd = request.context.get('cwd')

            # 任务描述（通过 stdin 传入）
            task_text = request.task
            if request.context.get('instructions'):
                task_text = f"{request.context['instructions']}\n\n{task_text}"

            # 启动子进程
            timeout_s = min(request.timeout_ms, self._timeout_ms) / 1000
            proc = await asyncio.create_subprocess_exec(
                *cmd,
                stdin=asyncio.subprocess.PIPE,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.PIPE,
                cwd=cwd,
            )

            # 通过 stdin 传入任务
            stdout, stderr = await asyncio.wait_for(
                proc.communicate(input=task_text.encode('utf-8')),
                timeout=timeout_s,
            )

            duration = (asyncio.get_event_loop().time() - start) * 1000

            if proc.returncode != 0:
                err_msg = stderr.decode('utf-8', errors='replace').strip()
                return SubagentResult(
                    success=False,
                    error=f'Codex 执行失败 (exit {proc.returncode}): {err_msg[:500]}',
                    provider=self.name,
                    duration_ms=duration,
                )

            # 解析 JSON 输出
            output_text = stdout.decode('utf-8', errors='replace').strip()
            result_text = self._parse_codex_output(output_text)

            return SubagentResult(
                success=True,
                output=result_text,
                provider=self.name,
                duration_ms=duration,
                metadata={'model': self._model, 'raw_length': len(output_text)},
            )

        except asyncio.TimeoutError:
            # 超时时尝试终止子进程
            try:
                proc.kill()
            except Exception:
                pass
            return SubagentResult(
                success=False,
                error=f'Codex 执行超时 ({self._timeout_ms}ms)',
                provider=self.name,
                duration_ms=self._timeout_ms,
            )
        except Exception as e:
            logger.debug('Codex 子 Agent 执行失败', exc_info=True)
            return SubagentResult(
                success=False,
                error=str(e),
                provider=self.name,
            )

    def _parse_codex_output(self, raw: str) -> str:
        """解析 codex exec --json 的输出。

        codex exec --json 输出多行 JSON 事件流，
        提取最终的 assistant message 作为结果。
        """
        import json as _json
        lines = raw.strip().split('\n')
        final_answer = ''

        for line in lines:
            line = line.strip()
            if not line:
                continue
            try:
                event = _json.loads(line)
            except _json.JSONDecodeError:
                # 非 JSON 行，直接作为文本输出
                continue

            # 提取 agentMessage 类型的事件
            if isinstance(event, dict):
                etype = event.get('type', '')
                if etype == 'item.completed' or etype == 'turn.completed':
                    item = event.get('item', {})
                    if isinstance(item, dict) and item.get('type') == 'agentMessage':
                        text = item.get('text', '')
                        if text:
                            final_answer = text
                elif etype == 'result':
                    # 某些版本直接返回 result
                    final_answer = event.get('result', '') or final_answer

        # 如果没解析到结构化结果，返回原始文本（去掉 JSON 行）
        if final_answer:
            return final_answer

        # 回退：返回所有非 JSON 行
        text_lines = []
        for line in lines:
            try:
                _json.loads(line.strip())
            except (_json.JSONDecodeError, ValueError):
                text_lines.append(line)
        return '\n'.join(text_lines).strip() if text_lines else raw[:2000]

    def health_check(self) -> dict:
        available = self._check_available()
        return {
            'provider': self.name,
            'status': 'ok' if available else 'unavailable',
            'codex_bin': self._codex_bin,
            'model': self._model,
            'available': available,
        }


# ─────────────────────────────────────────
# Qoder CLI Provider（参考 qodercli -p 非交互模式）
# ─────────────────────────────────────────

class QoderSubagentProvider:
    """Qoder CLI 子 Agent Provider。

    参考 better-harness 的 qodercli -p 非交互模式：
    - 通过 `qodercli -p "<prompt>"` CLI 子进程调用 Qoder
    - 支持 --cwd 指定工作目录
    - 纯文本输出解析
    - 自动审批（--yolo 跳过确认）

    底层调用：
        qodercli -p "任务描述" [--cwd /path] [--yolo]

    配置项（config.json 或 DEFAULTS）：
        qoder_command: qodercli 可执行文件路径（默认 "qodercli"）
        qoder_timeout: 超时毫秒数（默认 120000）
        qoder_yolo: 是否跳过确认（默认 True）
    """

    def __init__(self, config=None):
        self._config = config or {}
        self._qoder_bin = self._config.get('qoder_command', 'qodercli')
        self._timeout_ms = int(self._config.get('qoder_timeout', 120_000))
        self._yolo = self._config.get('qoder_yolo', True)
        self._env = self._config.get('env')  # 工具凭据（如 QODER_PERSONAL_ACCESS_TOKEN）
        self._available = None  # 懒检测

    @property
    def name(self) -> str:
        return 'qoder'

    @property
    def description(self) -> str:
        return 'Qoder CLI 子 Agent（qodercli -p 非交互模式）'

    def _find_binary(self) -> tuple:
        """查找 qodercli，委托给 find_binary_simple()。

        返回 (路径, 状态):
        - (path, "found") — 找到且在 PATH 中
        - (path, "found_not_in_path") — 找到但不在 PATH（需配置）
        - (None, "not_installed") — 未安装
        """
        from .tool_probe import find_binary_simple
        return find_binary_simple(self._qoder_bin)

    def _check_available(self) -> bool:
        """检测 qodercli 是否可用（结果缓存）。"""
        if self._available is not None:
            return self._available
        found, status = self._find_binary()
        self._available = found is not None
        self._found_path = found  # 缓存路径供错误提示
        self._find_status = status  # 缓存状态
        if self._available:
            logger.info('Qoder CLI 已检测: %s (路径: %s, 状态: %s)',
                        self._qoder_bin, found, status)
        else:
            logger.debug('Qoder CLI 未找到: %s', self._qoder_bin)
        return self._available

    async def execute(self, request: SubagentRequest) -> SubagentResult:
        start = asyncio.get_event_loop().time()

        binary, status = self._find_binary()
        if not binary:
            # 明确区分：未安装
            return SubagentResult(
                success=False,
                error=(
                    f'Qoder CLI 未安装。请访问 https://qoder.com 下载安装，'
                    f'或使用命令: curl -fsSL https://qoder.com/install.sh | bash'
                ),
                provider=self.name,
            )

        try:
            # 构建 qodercli 命令（使用完整路径）
            cmd = [binary]

            # 非交互模式：-p "<prompt>"
            task_text = request.task
            if request.context.get('instructions'):
                task_text = f"{request.context['instructions']}\n\n{task_text}"
            cmd.extend(['-p', task_text])

            # 工作目录
            cwd = request.context.get('cwd')
            if cwd:
                cmd.extend(['--cwd', cwd])

            # 跳过确认（全自动模式）
            if self._yolo:
                cmd.append('--yolo')

            # 环境变量（注入 QODER_PERSONAL_ACCESS_TOKEN 等工具凭据 + 扩展 PATH）
            env = dict(os.environ)
            if self._env:
                env.update({k: v for k, v in self._env.items() if v})
                logger.debug("QoderSubagentProvider 传递环境变量: %s",
                             [k for k, v in self._env.items() if v])

            # 扩展 PATH：补齐 ~/.local/bin 等常见 CLI 安装目录
            home = os.path.expanduser('~')
            extra_dirs = [
                os.path.join(home, '.local', 'bin'),
                os.path.join(home, '.qoder', 'bin', 'qodercli'),
                '/usr/local/bin',
                '/opt/homebrew/bin',
                os.path.join(home, '.npm-global', 'bin'),
                os.path.join(home, '.volta', 'bin'),
                os.path.join(home, '.bun', 'bin'),
            ]
            path_dirs = [d for d in extra_dirs if os.path.isdir(d)]
            if path_dirs:
                env['PATH'] = os.pathsep.join(path_dirs + [env.get('PATH', '')])

            # 启动子进程
            timeout_s = min(request.timeout_ms, self._timeout_ms) / 1000
            proc = await asyncio.create_subprocess_exec(
                *cmd,
                stdin=asyncio.subprocess.DEVNULL,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.PIPE,
                cwd=cwd,
                env=env,
            )

            # 等待完成
            stdout, stderr = await asyncio.wait_for(
                proc.communicate(),
                timeout=timeout_s,
            )

            duration = (asyncio.get_event_loop().time() - start) * 1000

            if proc.returncode != 0:
                err_msg = stderr.decode('utf-8', errors='replace').strip()
                return SubagentResult(
                    success=False,
                    error=f'Qoder 执行失败 (exit {proc.returncode}): {err_msg[:500]}',
                    provider=self.name,
                    duration_ms=duration,
                )

            # 解析纯文本输出
            output_text = stdout.decode('utf-8', errors='replace').strip()
            result_text = self._parse_qoder_output(output_text)

            return SubagentResult(
                success=True,
                output=result_text,
                provider=self.name,
                duration_ms=duration,
                metadata={'raw_length': len(output_text)},
            )

        except asyncio.TimeoutError:
            try:
                proc.kill()
            except Exception:
                pass
            return SubagentResult(
                success=False,
                error=f'Qoder 执行超时 ({self._timeout_ms}ms)',
                provider=self.name,
                duration_ms=self._timeout_ms,
            )
        except Exception as e:
            logger.debug('Qoder 子 Agent 执行失败', exc_info=True)
            return SubagentResult(
                success=False,
                error=str(e),
                provider=self.name,
            )

    def _parse_qoder_output(self, raw: str) -> str:
        """解析 qodercli -p 的输出。

        qodercli 输出为纯文本（Markdown 格式），
        去掉 ANSI 转义序列后直接返回。
        """
        import re
        # 去掉 ANSI 转义序列
        text = re.sub(r'\x1b\[[0-9;]*[a-zA-Z]', '', raw)
        # 去掉开头可能的 spinner / 进度行（以 \r 开头的行）
        lines = text.split('\n')
        clean_lines = []
        for line in lines:
            stripped = line.lstrip('\r')
            # 跳过纯进度行（以 ⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏ 等 spinner 字符开头）
            if stripped and stripped[0] in '⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏▏▎▍▌▋▊▉':
                continue
            clean_lines.append(line)
        result = '\n'.join(clean_lines).strip()
        return result if result else raw[:2000]

    def health_check(self) -> dict:
        available = self._check_available()
        return {
            'provider': self.name,
            'status': 'ok' if available else 'unavailable',
            'qoder_bin': self._qoder_bin,
            'available': available,
        }


# ─────────────────────────────────────────
# Claude Code CLI Provider（参考 LongHorizon-Harness claude_code 适配器）
# ─────────────────────────────────────────

class ClaudeCodeSubagentProvider:
    """Claude Code CLI 子 Agent Provider。

    参考 LongHorizon-Harness 的 claude_code 适配器：
    - 通过 `claude --print --output-format stream-json` 非交互调用
    - stream-json（JSONL）事件流解析，提取 assistant 文本
    - 自动跳过权限确认（--dangerously-skip-permissions）
    - prompt 通过 stdin 传入

    底层调用：
        claude --print --output-format stream-json --verbose \
            [--dangerously-skip-permissions] --model <model>

    配置项（config.json 或 DEFAULTS）：
        claude_code_command: claude 可执行文件路径（默认 "claude"）
        claude_code_model: 使用的模型（默认 "claude-sonnet-4-20250514"）
        claude_code_timeout: 执行超时秒数（默认 600）
        claude_code_skip_permissions: 是否跳过权限确认（默认 True）
        env: 额外环境变量（如 ANTHROPIC_API_KEY），可选
    """

    def __init__(self, config=None):
        self._config = config or {}
        # 兼容 claude_code_command / claude_command 两种键名（安装器旧路径）
        self._claude_bin = (self._config.get('claude_code_command')
                            or self._config.get('claude_command') or 'claude')
        self._model = (self._config.get('claude_code_model')
                       or self._config.get('claude_model')
                       or 'claude-sonnet-4-20250514')
        self._timeout_s = self._resolve_timeout()
        self._skip_permissions = self._config.get(
            'claude_code_skip_permissions', True)
        self._env = self._config.get('env') or None
        self._available = None  # 懒检测

    def _resolve_timeout(self) -> int:
        """解析超时（秒）。

        优先读取 claude_code_timeout（单位秒）；缺失时兼容旧安装器传入的
        claude_timeout（单位毫秒），转换为秒。
        """
        val = self._config.get('claude_code_timeout')
        if val is not None:
            return max(1, int(val))
        legacy = self._config.get('claude_timeout')
        if legacy is not None:
            return max(1, int(legacy) // 1000)
        return 600

    @property
    def name(self) -> str:
        return 'claude-code'

    @property
    def description(self) -> str:
        return f'Claude Code CLI 子 Agent（模型: {self._model}）'

    def _check_available(self) -> bool:
        """检测 claude CLI 是否可用（结果缓存）。"""
        if self._available is not None:
            return self._available
        import shutil
        self._available = shutil.which(self._claude_bin) is not None
        if self._available:
            logger.info('Claude Code CLI 已检测: %s', self._claude_bin)
        else:
            logger.debug('Claude Code CLI 未找到: %s', self._claude_bin)
        return self._available

    async def execute(self, request: SubagentRequest) -> SubagentResult:
        from .tool_probe import find_binary_simple
        start = asyncio.get_event_loop().time()

        binary, status = find_binary_simple(self._claude_bin)
        if not binary:
            return SubagentResult(
                success=False,
                error=(
                    f'Claude Code CLI 未安装。请运行: npm install -g @anthropic-ai/claude-code'
                ),
                provider=self.name,
            )

        proc = None
        try:
            # 构建 claude 命令（使用完整路径）
            cmd = [binary, '--print',
                   '--output-format', 'stream-json', '--verbose']

            # 跳过权限确认（全自动执行）
            if self._skip_permissions:
                cmd.append('--dangerously-skip-permissions')

            # 模型选择
            if self._model:
                cmd.extend(['--model', self._model])

            # 工作目录
            cwd = request.context.get('cwd')

            # 任务描述（通过 stdin 传入）
            task_text = request.task
            if request.context.get('instructions'):
                task_text = f"{request.context['instructions']}\n\n{task_text}"

            # 环境变量（注入 ANTHROPIC_API_KEY 等工具凭据）
            env = None
            if self._env:
                env = dict(os.environ)
                env.update({k: v for k, v in self._env.items() if v})

            # 启动子进程
            timeout_s = min(request.timeout_ms / 1000, self._timeout_s)
            proc = await asyncio.create_subprocess_exec(
                *cmd,
                stdin=asyncio.subprocess.PIPE,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.PIPE,
                cwd=cwd,
                env=env,
            )

            # 通过 stdin 传入任务
            stdout, stderr = await asyncio.wait_for(
                proc.communicate(input=task_text.encode('utf-8')),
                timeout=timeout_s,
            )

            duration = (asyncio.get_event_loop().time() - start) * 1000

            if proc.returncode != 0:
                err_msg = stderr.decode('utf-8', errors='replace').strip()
                return SubagentResult(
                    success=False,
                    error=f'Claude Code 执行失败 (exit {proc.returncode}): {err_msg[:500]}',
                    provider=self.name,
                    duration_ms=duration,
                )

            # 解析 stream-json 输出
            output_text = stdout.decode('utf-8', errors='replace').strip()
            result_text = self._parse_claude_output(output_text)

            return SubagentResult(
                success=True,
                output=result_text,
                provider=self.name,
                duration_ms=duration,
                metadata={'model': self._model, 'raw_length': len(output_text)},
            )

        except asyncio.TimeoutError:
            # 超时时尝试终止子进程
            try:
                if proc is not None:
                    proc.kill()
            except Exception:
                pass
            return SubagentResult(
                success=False,
                error=f'Claude Code 执行超时 ({self._timeout_s}s)',
                provider=self.name,
                duration_ms=self._timeout_s * 1000,
            )
        except Exception as e:
            logger.debug('Claude Code 子 Agent 执行失败', exc_info=True)
            return SubagentResult(
                success=False,
                error=str(e),
                provider=self.name,
            )

    def _parse_claude_output(self, raw: str) -> str:
        """解析 claude --output-format stream-json 的 JSONL 事件流。

        合并所有 type="assistant" 事件中 content block（type="text"）的文本；
        若存在 type="result" 的最终结果则优先采用。
        """
        import json as _json
        lines = raw.strip().split('\n')
        assistant_texts = []
        final_result = ''

        for line in lines:
            line = line.strip()
            if not line:
                continue
            try:
                event = _json.loads(line)
            except (_json.JSONDecodeError, ValueError):
                continue
            if not isinstance(event, dict):
                continue

            etype = event.get('type', '')
            if etype == 'assistant':
                message = event.get('message', {})
                content = message.get('content', []) if isinstance(message, dict) else []
                if isinstance(content, list):
                    for block in content:
                        if isinstance(block, dict) and block.get('type') == 'text':
                            text = block.get('text', '')
                            if text:
                                assistant_texts.append(text)
            elif etype == 'result':
                res = event.get('result', '')
                if isinstance(res, str) and res:
                    final_result = res

        if final_result:
            return final_result
        if assistant_texts:
            return '\n'.join(assistant_texts).strip()

        # 回退：返回所有非 JSON 行
        text_lines = []
        for line in lines:
            try:
                _json.loads(line.strip())
            except (_json.JSONDecodeError, ValueError):
                if line.strip():
                    text_lines.append(line)
        return '\n'.join(text_lines).strip() if text_lines else raw[:2000]

    def health_check(self) -> dict:
        available = self._check_available()
        return {
            'provider': self.name,
            'status': 'ok' if available else 'unavailable',
            'claude_bin': self._claude_bin,
            'model': self._model,
            'available': available,
        }


# ─────────────────────────────────────────
# Provider 工厂（供 SubagentManager / ToolInstaller 复用）
# ─────────────────────────────────────────

# 由工具系统管理的 CLI Provider 名称（refresh_from_tools 仅对这些做自动注销）
TOOL_MANAGED_PROVIDERS = {'codex', 'qoder', 'claude-code'}


def build_provider_by_name(name: str, params: dict = None, env: dict = None):
    """按 provider_name 构造对应 SubagentProvider 实例（未知则返回 None）。

    统一 Provider 构造逻辑，供 SubagentManager.refresh_from_tools 与
    ToolInstaller._build_provider 复用。params 通常为 RuntimeConfig.params。
    """
    params = params or {}
    if name == 'codex':
        return CodexSubagentProvider(config={
            'codex_command': params.get('codex_command', 'codex'),
            'codex_model': params.get('codex_model', 'gpt-5.4'),
            'codex_timeout': params.get('codex_timeout', 120000),
            'codex_bypass_sandbox': params.get('codex_bypass_sandbox', True),
            'env': env,
        })
    if name == 'qoder':
        return QoderSubagentProvider(config={
            'qoder_command': params.get('qoder_command', 'qodercli'),
            'qoder_timeout': params.get('qoder_timeout', 120000),
            'qoder_yolo': params.get('qoder_yolo', True),
            'env': env,
        })
    if name == 'claude-code':
        return ClaudeCodeSubagentProvider(config={
            'claude_code_command': params.get('claude_code_command', 'claude'),
            'claude_code_model': params.get('claude_code_model',
                                            'claude-sonnet-4-20250514'),
            'claude_code_timeout': params.get('claude_code_timeout', 600),
            'claude_code_skip_permissions': params.get(
                'claude_code_skip_permissions', True),
            'env': env,
        })
    return None


# ─────────────────────────────────────────
# Subagent Manager
# ─────────────────────────────────────────

class SubagentManager:
    """子 Agent 管理器 — 统一管理多 Provider。

    用法:
        manager = SubagentManager()
        manager.register(InProcessProvider(llm, tools))
        manager.register(A2ASubagentProvider(caller))
        result = await manager.execute(SubagentRequest(task="..."))
    """

    def __init__(self):
        self._providers: dict[str, SubagentProviderProtocol] = {}
        self._default_provider: Optional[str] = None
        self._lock = threading.RLock()      # 并发安全：register/unregister/refresh
        self._provider_factory: Optional[Callable[..., Any]] = None

    def set_provider_factory(self, factory: Callable[..., Any]) -> None:
        """设置 Provider 构造工厂：callable(name, params) -> provider | None。

        未设置时 refresh_from_tools 使用内置 build_provider_by_name。
        """
        self._provider_factory = factory

    def register(self, provider: SubagentProviderProtocol, default: bool = False) -> None:
        """注册一个 Provider（同名覆盖，运行时可安全调用）。"""
        with self._lock:
            self._providers[provider.name] = provider
            if default or self._default_provider is None:
                self._default_provider = provider.name
        logger.info('注册子 Agent Provider: %s', provider.name)

    def unregister(self, name: str) -> None:
        """注销一个 Provider（运行时可安全调用）。"""
        with self._lock:
            self._providers.pop(name, None)
            if self._default_provider == name:
                self._default_provider = next(iter(self._providers), None)

    def refresh_from_tools(self, installations: list, params: dict = None) -> dict:
        """根据工具安装记录刷新 Provider 注册状态（运行时热注册/注销）。

        Args:
            installations: 安装记录列表，每项为 dict 或含同名属性的对象，
                需提供 key/status/enabled，可选 provider_name/env_vars。
            params: 构造 Provider 时使用的运行参数（RuntimeConfig.params）。

        规则：
        - status=installed 且 enabled 且含 provider_name → 确保已注册
        - 已注册但不在期望集合中的受管 CLI Provider（codex/qoder/claude-code）
          → 注销；内置进程内/远程 Provider（in-process/a2a/fork）始终保留。
        """
        params = params or {}
        desired: dict = {}  # provider_name -> env_vars
        for item in installations or []:
            data = item if isinstance(item, dict) else getattr(item, '__dict__', {})
            status = data.get('status')
            enabled = data.get('enabled', True)
            provider_name = data.get('provider_name')
            env_vars = data.get('env_vars') or {}
            if status == 'installed' and enabled and provider_name:
                # 合并同一 provider 下多个工具的环境变量
                existing = desired.get(provider_name, {})
                existing.update(env_vars)
                desired[provider_name] = existing

        summary: dict = {'registered': [], 'kept': [], 'unregistered': []}
        with self._lock:
            # 注册缺失的 provider
            for name in sorted(desired):
                if name in self._providers:
                    summary['kept'].append(name)
                    continue
                provider = self._build_provider(name, params, env=desired[name])
                if provider is not None:
                    self._providers[name] = provider
                    if self._default_provider is None:
                        self._default_provider = name
                    summary['registered'].append(name)

            # 注销不再期望的受管 CLI provider
            for name in list(self._providers.keys()):
                if name in desired:
                    continue
                if name not in TOOL_MANAGED_PROVIDERS:
                    continue
                self._providers.pop(name, None)
                if self._default_provider == name:
                    self._default_provider = next(iter(self._providers), None)
                summary['unregistered'].append(name)

        if summary['registered'] or summary['unregistered']:
            logger.info('Provider 刷新完成: %s', summary)
        return summary

    def _build_provider(self, name: str, params: dict, env: dict = None):
        """按名称构造 Provider（优先用外部工厂，否则用内置工厂）。"""
        factory = self._provider_factory or build_provider_by_name
        try:
            return factory(name, params, env=env)
        except Exception:
            logger.exception('构造 Provider 失败: %s', name)
            return None

    def discover(self) -> list[dict]:
        """发现已注册的 Provider。"""
        return [
            {
                'name': p.name,
                'description': p.description,
                'healthy': p.health_check().get('status') == 'ok',
            }
            for p in self._providers.values()
        ]

    async def execute(self, request: SubagentRequest) -> SubagentResult:
        """执行子 Agent 任务。"""
        provider_name = request.provider or self._default_provider
        if not provider_name:
            return SubagentResult(success=False, error='无可用子 Agent Provider')

        provider = self._providers.get(provider_name)
        if not provider:
            return SubagentResult(
                success=False,
                error=f'Provider "{provider_name}" 未找到',
            )

        logger.info('子 Agent 执行: provider=%s, task=%s', provider_name, request.task[:100])
        return await provider.execute(request)

    def health_check_all(self) -> list[dict]:
        """所有 Provider 健康检查。"""
        return [p.health_check() for p in self._providers.values()]

    @property
    def providers(self) -> list[str]:
        return list(self._providers.keys())
